//go:build js && wasm

// This file is copied into golang.org/x/tools/go/packages by poc/wasm/build.sh.
//
// It provides an in-process replacement for the `go list` driver, because
// js/wasm cannot start subprocesses. It supports a single main module whose
// dependencies are limited to the standard library:
//
//   - packages of the main module are resolved with go/build (GOPATH mode,
//     so that go/build never tries to run `go list` itself);
//   - standard library packages are taken from a manifest pre-generated by
//     `go list -json std` (WASM_STD_MANIFEST), and their export data from
//     pre-generated files (WASM_EXPORT_DIR/<import path>.a).

package packages

import (
	"encoding/json"
	"fmt"
	"go/build"
	"os"
	"path/filepath"
	"runtime"
	"strconv"
	"strings"
)

func init() { inprocDriver = inprocListDriver }

type inprocStdPackage struct {
	Name    string            `json:"name"`
	Dir     string            `json:"dir"`
	GoFiles []string          `json:"goFiles"`
	Imports map[string]string `json:"imports"` // import path as written -> resolved import path
	Export  bool              `json:"export"`
}

func inprocListDriver(cfg *Config, patterns ...string) (*DriverResponse, error) {
	std := map[string]inprocStdPackage{}
	if b, err := os.ReadFile(os.Getenv("WASM_STD_MANIFEST")); err != nil {
		return nil, fmt.Errorf("inproc driver: reading std manifest: %w", err)
	} else if err := json.Unmarshal(b, &std); err != nil {
		return nil, fmt.Errorf("inproc driver: parsing std manifest: %w", err)
	}
	exportDir := os.Getenv("WASM_EXPORT_DIR")

	// GOPATH mode keeps go/build from invoking `go list`.
	os.Setenv("GO111MODULE", "off")
	ctxt := build.Default
	ctxt.GOOS, ctxt.GOARCH = "linux", "amd64"
	ctxt.CgoEnabled = false
	ctxt.GOROOT = os.Getenv("GOROOT")
	ctxt.GOPATH = ""
	ctxt.Compiler = "gc"

	dir := cfg.Dir
	if dir == "" {
		var err error
		if dir, err = os.Getwd(); err != nil {
			return nil, err
		}
	}
	mod := &Module{Path: "playground", Dir: dir, GoMod: filepath.Join(dir, "go.mod"), Main: true}
	if b, err := os.ReadFile(mod.GoMod); err == nil {
		for _, line := range strings.Split(string(b), "\n") {
			switch f := strings.Fields(line); {
			case len(f) == 2 && f[0] == "module":
				mod.Path = strings.Trim(f[1], `"`)
			case len(f) == 2 && f[0] == "go":
				mod.GoVersion = f[1]
			}
		}
	}

	resp := &DriverResponse{Compiler: "gc", Arch: "amd64", GoVersion: goMinorVersion()}
	byID := map[string]*Package{}

	var addStd func(id string) *Package
	addStd = func(id string) *Package {
		if p, ok := byID[id]; ok {
			return p
		}
		sp := std[id]
		p := &Package{ID: id, Name: sp.Name, PkgPath: id, Imports: map[string]*Package{}}
		if sp.Export {
			p.ExportFile = filepath.Join(exportDir, id+".a")
		}
		for _, f := range sp.GoFiles {
			p.GoFiles = append(p.GoFiles, filepath.Join(sp.Dir, f))
		}
		p.CompiledGoFiles = p.GoFiles
		byID[id] = p
		resp.Packages = append(resp.Packages, p)
		for path, resolved := range sp.Imports {
			p.Imports[path] = &Package{ID: addStd(resolved).ID}
		}
		return p
	}

	var addLocal func(pkgDir string) (*Package, error)
	addLocal = func(pkgDir string) (*Package, error) {
		rel, err := filepath.Rel(mod.Dir, pkgDir)
		if err != nil || strings.HasPrefix(rel, "..") {
			return nil, fmt.Errorf("inproc driver: %s is outside of the main module", pkgDir)
		}
		id := mod.Path
		if rel != "." {
			id += "/" + filepath.ToSlash(rel)
		}
		if p, ok := byID[id]; ok {
			return p, nil
		}
		bp, err := ctxt.ImportDir(pkgDir, 0)
		if err != nil {
			return nil, err
		}
		p := &Package{ID: id, Name: bp.Name, PkgPath: id, Module: mod, Imports: map[string]*Package{}}
		for _, f := range bp.GoFiles {
			p.GoFiles = append(p.GoFiles, filepath.Join(bp.Dir, f))
		}
		p.CompiledGoFiles = p.GoFiles
		for _, f := range bp.IgnoredGoFiles {
			p.IgnoredFiles = append(p.IgnoredFiles, filepath.Join(bp.Dir, f))
		}
		byID[id] = p
		resp.Packages = append(resp.Packages, p)
		for _, path := range bp.Imports {
			switch {
			case path == "C":
				p.Errors = append(p.Errors, Error{Msg: "cgo is not supported in the playground", Kind: ListError})
			case path == mod.Path || strings.HasPrefix(path, mod.Path+"/"):
				dep, err := addLocal(filepath.Join(mod.Dir, filepath.FromSlash(strings.TrimPrefix(path[len(mod.Path):], "/"))))
				if err != nil {
					p.Errors = append(p.Errors, Error{Msg: err.Error(), Kind: ListError})
					continue
				}
				p.Imports[path] = &Package{ID: dep.ID}
			default:
				if _, ok := std[path]; !ok {
					p.Errors = append(p.Errors, Error{
						Msg:  fmt.Sprintf("package %s is not in std (only the standard library is available in the playground)", path),
						Kind: ListError,
					})
					continue
				}
				p.Imports[path] = &Package{ID: addStd(path).ID}
			}
		}
		return p, nil
	}

	for _, pat := range patterns {
		recursive := pat == "..." || strings.HasSuffix(pat, "/...")
		base := filepath.Join(dir, strings.TrimSuffix(strings.TrimSuffix(pat, "..."), "/"))
		var dirs []string
		if recursive {
			err := filepath.WalkDir(base, func(path string, d os.DirEntry, err error) error {
				if err != nil || !d.IsDir() {
					return err
				}
				if n := d.Name(); path != base && (strings.HasPrefix(n, ".") || strings.HasPrefix(n, "_") || n == "testdata") {
					return filepath.SkipDir
				}
				dirs = append(dirs, path)
				return nil
			})
			if err != nil {
				return nil, err
			}
		} else {
			dirs = append(dirs, base)
		}
		for _, d := range dirs {
			p, err := addLocal(d)
			if err != nil {
				if _, ok := err.(*build.NoGoError); ok && recursive {
					continue
				}
				return nil, fmt.Errorf("inproc driver: %w", err)
			}
			resp.Roots = append(resp.Roots, p.ID)
		}
	}
	return resp, nil
}

// goMinorVersion returns the minor version of the Go release this binary
// was built with (e.g. 24 for go1.24.7). The bundled std must match it.
func goMinorVersion() int {
	v := strings.TrimPrefix(runtime.Version(), "go1.")
	if i := strings.IndexAny(v, ".rc beta"); i >= 0 {
		v = v[:i]
	}
	n, _ := strconv.Atoi(v)
	return n
}
